CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), phase TEXT NOT NULL DEFAULT 'setup', groups_json TEXT NOT NULL DEFAULT '["A","B","C","D","E","F","G","H"]');
INSERT OR IGNORE INTO settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS cards(id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 80),name TEXT NOT NULL,economy INTEGER NOT NULL,environment INTEGER NOT NULL,society INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trades(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id TEXT NOT NULL UNIQUE,group_name TEXT NOT NULL,card_id INTEGER NOT NULL,name TEXT NOT NULL,economy INTEGER NOT NULL,environment INTEGER NOT NULL,society INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),voided INTEGER NOT NULL DEFAULT 0,void_reason TEXT,voided_at TEXT);
